// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockTime, uint256 blockNumber) public {
        vm.assume(amount == 10 ether);
        vm.assume(blockTime > c.pastBlockTime());
        vm.warp(blockTime);
        vm.roll(blockNumber);

        (bool sent, ) = address(c).call{value: amount}("");

        assertTrue(sent == false || c.pastBlockTime() > blockTime);
    }
}

